import{z as l,x as o,o as e,c as m,q as i,j as B,D as E,d as t,s as A,S as s,b as r}from"./chunks/framework.C8m1ZpeB.js";const V=JSON.parse('{"title":"跳跃的检测与处理","description":"","frontmatter":{"title":"跳跃的检测与处理","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/hfs-jump-detection.md","filePath":"quant/hfs-jump-detection.md","lastUpdated":1791413859000}'),d={name:"quant/hfs-jump-detection.md"};function h(p,a,C,c,u,D){const n=o("Mermaid");return e(),m("div",null,[a[2]||(a[2]=i('<h1 id="跳跃的检测与处理" tabindex="-1">跳跃的检测与处理 <a class="header-anchor" href="#跳跃的检测与处理" aria-label="Permalink to &quot;跳跃的检测与处理&quot;">​</a></h1><div class="epigraph"><p>二次变差不区分连续积累与瞬间位移；先把 RV 减去双幂次，再除以自己的波动，差值才有临界值可读。</p><footer>—— Barndorff-Nielsen and Shephard, Journal of Financial Econometrics, 2006</footer></div><p><a href="/quant/hfs-noise-corrected">上一课</a>把噪声修正支收成对照，积分波动有了在噪声下一致的估计；族谱的跳这一轴还没动。\\(\\mathrm{RV}\\) 收敛到的是总二次变差 \\(IV+\\sum_s(\\Delta X_s)^2\\)，而风控与对冲要的常常只是连续部分。检验地图已在<a href="/quant/jump-tests">跳跃检验</a>与<a href="/quant/bn-jump-test">Barndorff-Nielsen 跳跃检验</a>写过，符号拆分在<a href="/quant/realized-semivariance">已实现半方差与符号跳跃</a>写过；本课收窄到<strong>检测之后的处理</strong>：一次显著的跳对估计量、预报与风险各改什么，噪声在场时整套流程的次序怎么排。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日度检验统计量 \\(Z=(\\mathrm{RV}-\\mathrm{BV})/\\sqrt{\\theta\\cdot \\widehat{\\mathrm{QV}}}\\) 在无跳原假设下渐近标准正态：\\(\\mathrm{BV}\\) 是双幂次变差，渐近方差里的 quarticity 用多幂次估计补齐（Barndorff-Nielsen 与 Shephard，2004/2006）。日度检验只回答「今天有没有」，不回答几点、多大、对哪个量修正多少。Lee 与 Mykland（2008）用局部窗口把统计量压到日内找时点；门限法（Mancini，2001）直接比较单格收益 \\(|\\Delta X|\\) 与 \\(\\alpha\\sigma_i\\Delta^{\\varphi}\\)。缺口是把检测器接进流程：检出的跳从哪里扣、扣给谁、不扣会污染什么。</p><p><span class="marginnote">术语翻译：双幂次变差 BV 就是「相邻两个绝对收益相乘再求和」，即累加 \\(|r_i|\\times|r_{i+1}|\\)。一次跳最多落在相邻的一格里，乘积的另一个因子仍是普通小收益，跳的影响被稀释成线性——所以加总后它仍能近似连续波动，这就是它「稳健」的全部秘密。</span></p><h3 id="流水线-先降噪-再检验-后拆账" tabindex="-1">流水线：先降噪，再检验，后拆账 <a class="header-anchor" href="#流水线-先降噪-再检验-后拆账" aria-label="Permalink to &quot;流水线：先降噪，再检验，后拆账&quot;">​</a></h3><p>噪声在场时次序不能乱。第一步降噪：用上一课的核或预平均得到噪声稳健的 \\(\\widehat{IV}\\) 与逐点波动估计——朴素 RV 与 BV 都被 \\(2n\\sigma_\\varepsilon^2\\) 量级的项污染，直接相减的检验 size 会坏。第二步日度检验：在降噪后的收益上算 \\(Z\\) 与相对份额 \\(\\mathrm{RJ}=(\\mathrm{RV}-\\mathrm{BV})/\\mathrm{RV}\\)。第三步定位：Lee–Mykland 的局部统计量找时点，或按门限把单格收益标记为跳。第四步拆账：连续部分 \\(C\\) 与跳部分 \\(J\\) 分别记账，供预报与风控各取所需。</p><p><span class="marginnote">一年 252 个交易日、每天一次 99.9% 水平的检验，假阳性期望约四分之一天；开盘季节性没除净时，一天能误报出十次「跳」。误差在季节性，不在临界值。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>处理按用途分账。<strong>估连续部分</strong>：门限法把超限收益置零后加总，或直接用 BV——两者在有限活动跳下都一致估 \\(IV\\)；报告时声明是「每天拆」还是「仅在显著日拆」，两种口径的 \\(C\\) 序列不可混用。<strong>供预报</strong>：把 \\(C\\) 与 \\(J\\) 分别喂进 HAR（多步口径见<a href="/quant/har-rv-forecast">HAR-RV 多尺度预测</a>），跳是瞬时项、几乎不进自相关，混在一起会抬高持续性、拉坏多步预报。<strong>供风险</strong>：下行半方差与符号跳跃把负跳单列，尾部分析与期权对冲用的是这一路，不是无符号的 \\(Z\\)。<strong>供事件研究</strong>：Lee–Mykland 的时点与符号本身就是事件标记，跳幅度 \\(\\Delta X_\\tau\\) 直接进事件窗。</p><p><span class="marginnote">数字实例：某日降噪后 \\(\\mathrm{RV}=4\\)（%²）、\\(\\mathrm{BV}=3\\)，则相对份额 \\(\\mathrm{RJ}=(4-3)/4=25\\%\\)——当天约四分之一的二次变差记在跳的账上；但只有 \\(Z\\) 统计量也超过 99.9% 临界值，这笔账才被当真，否则只是普通波动。</span></p>',12)),(e(),B(s,null,{default:E(()=>[A(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E9%99%8D%E5%99%AA%EF%BC%9A%E6%A0%B8%E6%88%96%E9%A2%84%E5%B9%B3%E5%9D%87%E7%9A%84%20IV%20%E4%B8%8E%E9%80%90%E7%82%B9%E6%B3%A2%E5%8A%A8%22%5D%20--%3E%20Z%5B%22%E6%97%A5%E5%BA%A6%E6%A3%80%E9%AA%8C%20Z%20%E4%B8%8E%20RJ%22%5D%0A%20%20Z%20--%3E%7C%22%E6%98%BE%E8%91%97%22%7C%20L%5B%22%E5%AE%9A%E4%BD%8D%EF%BC%9ALee%E2%80%93Mykland%20%E6%88%96%E9%97%A8%E9%99%90%22%5D%0A%20%20Z%20--%3E%7C%22%E4%B8%8D%E6%98%BE%E8%91%97%22%7C%20C1%5B%22C%20%3D%20%E5%85%A8%E9%83%A8%EF%BC%8CJ%20%3D%200%22%5D%0A%20%20L%20--%3E%20S%5B%22%E6%8B%86%E8%B4%A6%EF%BC%9AC%20%E8%BF%9E%E7%BB%AD%E9%83%A8%E5%88%86%EF%BC%8CJ%20%E8%B7%B3%E9%83%A8%E5%88%86%22%5D%0A%20%20C1%20--%3E%20U%0A%20%20S%20--%3E%20U%5B%22%E5%88%86%E8%B4%A6%E4%BD%BF%E7%94%A8%EF%BC%9A%E9%A2%84%E6%8A%A5%E3%80%81%E9%A3%8E%E9%99%A9%E3%80%81%E4%BA%8B%E4%BB%B6%E5%90%84%E5%8F%96%E6%89%80%E9%9C%80%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[t("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,"双幂次为什么稳健：相邻绝对收益的乘积 \\(|r_i|\\,|r_{i+1}|\\) 把一次大跳只线性地放进一个因子，其贡献是 \\(O(|\\Delta X|\\cdot\\sqrt{\\Delta})\\) 量级，随 \\(\\Delta\\) 消失；于是 BV 仍收敛到 \\(IV\\)，差值 \\(\\mathrm{RV}-\\mathrm{BV}\\) 收敛到跳的平方和。有限活动是前提——无穷多次小跳会让「连续与瞬时」的边界本身失效。处理错误的代价不对称：把连续波动误判成跳，当天 \\(IV\\) 被削、波动预报偏低；把跳留在 \\(C\\) 里，预报与对冲把它当成会重复的过程，事件之后继续付对冲成本。两种错误共享同一个根源——用阈值直觉代替有 size 的检验。",-1)),(e(),B(s,null,{default:E(()=>[A(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20E%7B%22%E6%A3%80%E9%AA%8C%E5%88%A4%E9%94%99%E4%BA%86%2C%20%E5%90%8E%E6%9E%9C%E6%98%AF%E4%BB%80%E4%B9%88%3F%22%7D%20--%3E%7C%22%E6%8A%8A%E8%BF%9E%E7%BB%AD%E6%B3%A2%E5%8A%A8%E8%AF%AF%E5%88%A4%E6%88%90%E8%B7%B3%22%7C%20T1%5B%22%E5%BD%93%E5%A4%A9%20IV%20%E8%A2%AB%E5%89%8A%E6%8E%89%E4%B8%80%E5%9D%97%22%5D%0A%20%20T1%20--%3E%20T2%5B%22%E6%B3%A2%E5%8A%A8%E9%A2%84%E6%8A%A5%E5%81%8F%E4%BD%8E%2C%20%E9%A3%8E%E6%8E%A7%E5%81%8F%E6%9D%BE%22%5D%0A%20%20E%20--%3E%7C%22%E6%8A%8A%E8%B7%B3%E7%95%99%E5%9C%A8%E8%BF%9E%E7%BB%AD%E8%B4%A6%20C%20%E9%87%8C%22%7C%20F1%5B%22%E9%A2%84%E6%8A%A5%E6%8A%8A%E8%B7%B3%E5%BD%93%E6%88%90%E4%BC%9A%E9%87%8D%E5%A4%8D%E7%9A%84%E8%BF%87%E7%A8%8B%22%5D%0A%20%20F1%20--%3E%20F2%5B%22%E4%BA%8B%E4%BB%B6%E4%B9%8B%E5%90%8E%E7%BB%A7%E7%BB%AD%E4%BB%98%E5%AF%B9%E5%86%B2%E6%88%90%E6%9C%AC%22%5D%0A%20%20ROOT%5B%22%E5%85%B1%E5%90%8C%E6%A0%B9%E6%BA%90%3A%20%E7%94%A8%E9%98%88%E5%80%BC%E7%9B%B4%E8%A7%89%E4%BB%A3%E6%9B%BF%E6%9C%89%20size%20%E7%9A%84%E6%A3%80%E9%AA%8C%22%5D%20--%3E%20E%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p><span class="marginnote">直觉类比：\\(|r_i|\\,|r_{i+1}|\\) 像两人抬杠——一格有跳，等于一个大力士搭一个普通人，总载荷被普通人封顶，大力士的力气发挥不出来（线性进账）；连续波动则是两个普通人正常抬（随格距累加）。跳因此不会像在 RV 里那样平方级炸开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>流程不判断跳的经济成因：显著位移只说明二次变差里有一笔瞬时账，是消息还是流动性断裂，要接事件与市场状态分析。噪声极强或数据极脏时，size 修正做不干净，宁可降频到签名图平坦处再做日度检验。小跳与模糊区的功效有限：检不出不等于不存在，「未检出」要带功效口径报告，不能写成「无跳」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>次序固定：先降噪，再日度检验，后定位与拆账；乱序让 size 先坏。</li><li>BV 与门限在有限活动跳下一致估连续部分；\\(Z\\) 给显著性，\\(\\mathrm{RJ}\\) 给份额，局部统计量给时点。</li><li>分账使用：预报接 HAR 用 \\(C\\) 与 \\(J\\)，风险接半方差与符号跳，事件接时点与幅度。</li><li>双幂次的机制是线性进因子：单次大跳随 \\(\\Delta\\) 消失；前提是有限活动。</li><li>两种处理错误代价不对称：误判跳削 \\(IV\\)，漏判跳污染预报与对冲。</li><li>出处：Barndorff-Nielsen and Shephard, <em>Journal of Financial Econometrics</em>, 2004 与 2006；Lee and Mykland, <em>Review of Financial Studies</em>, 2008；Mancini, 2001（门限估计）。</li></ul>',5))])}const _=l(d,[["render",h]]);export{V as __pageData,_ as default};
